using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class Industrivej : LayoutBase
{
    public Industrivej()
    {
        Name = LayoutNamesEnums.Industrivej;
        Owner = "";
        Description = "Industrivej, Danish rail freight in the 90s, represents the end of a freight only branch line serving a variety of industries near one of the larger Danish towns in the mid 1990s. It was inspired by a number of visits to Denmark, although research was mainly done using Google Earth to view this type of area in Naestved, Esbjerg, Copenhagen and Odense. The area portrayed features a scrap metal processor, a warehousing company and an animal feeds distributor, all typical Danish industries and all served by rail. The branch has been closed just beyond the level crossing but the section modelled is still very much in use, the idea being that more rail served industries exist off-scene, which allows a greater variety of wagons to appear. Locomotives and stock are a mix of weathered and detailed ready-to-run, kit-bashed ready-to-run and kit-built, with most locomotives sound fitted. The buildings are mostly scratch-built or kit-bashed following Danish prototypes, and the ground cover is dust from an electric tile cutter, dried and fixed with dilute acrylic varnish. The track is Peco code 70 ballasted with Woodland Scenics fine ballast, using medium radius points which give a railway-like look to a small layout.";
    }
}